13.query:
smartscapeNodes "HOST","SERVICE","PROCESS","K8S_CLUSTER","K8S_NAMESPACE","K8S_DEPLOYMENT","K8S_STATEFULSET","K8S_DAEMONSET","K8S_CRONJOB","FRONTEND","BROWSER_MONITOR"
| fieldsAdd AppID = coalesce(tags[AppID], tags[application_id])
| filter isNotNull(AppID) and AppID != ""
| filter in(AppID, array($AppID))
| summarize tagged_entities = count(), by:{AppID, type}
| fieldsAdd k = 1
| lookup [smartscapeNodes "HOST","SERVICE","PROCESS","K8S_CLUSTER","K8S_NAMESPACE","K8S_DEPLOYMENT","K8S_STATEFULSET","K8S_DAEMONSET","K8S_CRONJOB","FRONTEND","BROWSER_MONITOR" | summarize type_total = count(), by:{type}], sourceField:type, lookupField:type, fields:{type_total}
| lookup [smartscapeNodes "HOST","SERVICE","PROCESS","K8S_CLUSTER","K8S_NAMESPACE","K8S_DEPLOYMENT","K8S_STATEFULSET","K8S_DAEMONSET","K8S_CRONJOB","FRONTEND","BROWSER_MONITOR" | fieldsAdd AppID = coalesce(tags[AppID], tags[application_id]) | filter isNotNull(AppID) and AppID != "" | summarize entities_per_AppID = count(), by:{AppID}], sourceField:AppID, lookupField:AppID, fields:{entities_per_AppID}
| lookup [smartscapeNodes "HOST","SERVICE","PROCESS","K8S_CLUSTER","K8S_NAMESPACE","K8S_DEPLOYMENT","K8S_STATEFULSET","K8S_DAEMONSET","K8S_CRONJOB","FRONTEND","BROWSER_MONITOR" | summarize estate_total = count() | fieldsAdd k = 1], sourceField:k, lookupField:k, fields:{estate_total}
| fieldsAdd coverage_pct_of_type = round(tagged_entities * 100.0 / type_total, decimals:1), coverage_pct_of_estate = round(entities_per_AppID * 100.0 / estate_total, decimals:1)
| fields AppID, type, tagged_entities, type_total, coverage_pct_of_type, entities_per_AppID, coverage_pct_of_estate
| sort AppID asc, type asc
